var runtime=typeof(EchoSphere.Runtime.EchoSphereRuntime);var flags=System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Static;var source=(EchoSphere.Presentation.V)runtime.Assembly.GetType("EchoSphere.Presentation.Visual_engineProgression").GetField("Scope").GetValue(null);var catalog=EchoSphere.Presentation.NativeRunCatalog.Instance;int checks=0;
void Check(EchoSphere.Presentation.V scene,string id,bool ability,int stage){var actual=(EchoSphere.Presentation.V)runtime.GetMethod("NativeEvolutionChoices",flags).Invoke(null,new object[]{scene,id,ability,stage});var expected=source[ability?"getAbilityEvolutionChoices":"getSphereEvolutionChoices"].Call(scene,id,stage);if(actual["length"].Number!=expected["length"].Number)throw new System.Exception("count/"+id);for(int i=0;i<actual["length"].Number;i++){foreach(var key in new[]{"type","sphereType","sphereBranch","sphereFinalIndex","sphereStage","ability","abilityStage","abilityEvolutionIndex","currentLevel","newLevel"}){if(actual[i][key].Text!=expected[i][key].Text)throw new System.Exception(id+"/"+key);checks++;}foreach(var key in new[]{"name","desc"})foreach(var lang in new[]{"ru","en"}){if(actual[i][key][lang].Text!=expected[i][key][lang].Text)throw new System.Exception(id+"/"+key+"/"+lang);checks++;}var keyActual=(string)runtime.GetMethod("NativeUpgradeChoiceKey",flags).Invoke(null,new object[]{actual[i]});if(keyActual!=source["getUpgradeChoiceKey"].Call(expected[i]).Text)throw new System.Exception("key/"+id);checks++;}}
foreach(var sphere in catalog.Spheres){var branches=EchoSphere.Presentation.VisualJs.Obj();var scene=EchoSphere.Presentation.VisualJs.Obj("player",EchoSphere.Presentation.VisualJs.Obj("sphereBranches",branches));Check(scene,sphere.Id,false,4);foreach(var branch in sphere.Branches){branches[sphere.Id]=branch.Id;Check(scene,sphere.Id,false,7);}}
foreach(var ability in catalog.Abilities){var player=EchoSphere.Presentation.VisualJs.Obj("evolutions",EchoSphere.Presentation.VisualJs.Arr());var scene=EchoSphere.Presentation.VisualJs.Obj("player",player);Check(scene,ability.Id,true,4);Check(scene,ability.Id,true,7);foreach(var branch in ability.Branches){player["evolutions"]=EchoSphere.Presentation.VisualJs.Arr(new EchoSphere.Presentation.V("ability:"+ability.Id+":4:"+branch.Id));Check(scene,ability.Id,true,7);}}
return new {checks};
